function normalize(value) {

  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  if (
    value !== null &&
    typeof value === 'object'
  ) {

    const result = {};

    for (const key of Object.keys(value).sort()) {
      result[key] = normalize(value[key]);
    }

    return result;
  }

  return value;
}

function same(a, b) {
  return JSON.stringify(normalize(a)) ===
